// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.routerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.llm.cost.LlmCostTrackerimport com.roshan.persona.brain.llm.layer.CloudLlmLayerimport com.roshan.persona.brain.llm.layer.LocalLlmLayerimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.registry.CloudProviderRegistryimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.Resultimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Hybrid LLM router (sits on top of Layer 3 + Layer 4). * * Decides which LLM layer to invoke based on: *   - User privacy settings (cloud on/off) *   - User explicit request ("ask cloud: ...") *   - Local LLM availability (model loaded?) *   - Context length (long contexts may need cloud) *   - Local LLM failure / low confidence * * ## Routing Logic * *   1. **User explicit cloud** — if input starts with "ask cloud:" or user *      tapped "Verify with cloud" on a Partial response, go straight to *      [CloudLlmLayer] (if cloud is enabled). * *   2. **Long context** — if estimated prompt > local model's context length, *      skip local and go to cloud (if enabled). Local would fail anyway. * *   3. **Local-first** — try [LocalLlmLayer] first. If it returns: *        - Success → return immediately *        - Partial (low confidence) → return immediately with warning (privacy fix #6) *        - Failure (OOM/load failed) → fall back to cloud (if enabled) * *   4. **Cloud fallback** — if local failed AND cloud is enabled, try [CloudLlmLayer]. * *   5. **Both failed** — return a user-friendly error explaining both layers failed. * * ## Privacy Contract (per ADR 0011) * *   - Cloud is NEVER called automatically. It's called only when: *     a) User explicitly asked for cloud, OR *     b) Local failed AND user has cloud enabled in privacy settings. * *   - If cloud is disabled in privacy settings, local failures are surfaced *     to the user as errors (no auto-cloud). * * ## Streaming * * Both layers support streaming via [onToken] callback. The router passes * the callback through to whichever layer it invokes. * * @see <a href="docs/spec/module2-spec-review.pdf">§8.3 Hybrid Router</a> */@Singletonclass HybridLlmRouter @Inject constructor(    private val localLlmLayer: LocalLlmLayer,    private val cloudLlmLayer: CloudLlmLayer?,    private val contextInjector: ContextInjector,) {    /**     * Result of routing — for telemetry + UI feedback.     */    sealed interface RoutingDecision {        /** User explicitly asked for cloud (input started with "ask cloud:"). */        data object ExplicitCloud : RoutingDecision        /** User explicitly asked for local (input started with "ask local:"). */        data object ExplicitLocal : RoutingDecision        /** Context too long for local model — deferring to cloud. */        data class LongContext(val estimatedTokens: Int, val localContextLength: Int) : RoutingDecision        /** Local-first default — try local, fall back to cloud on failure. */        data object LocalFirst : RoutingDecision        /** Cloud is disabled and local failed — no fallback available. */        data object NoFallback : RoutingDecision    }    /**     * Process [userInput] through the hybrid LLM router.     *     * @param userInput the user's text input (already context-resolved by L0)     * @param context the brain context     * @param forceCloud if true, skip local and go straight to cloud     * @param forceLocal if true, skip cloud entirely (privacy mode for this call)     * @param preferredCloudProvider optional — when calling cloud, use this provider     * @param preferredCloudModel optional — when calling cloud, use this model     * @param generationConfig LLM sampling params     * @param onToken streaming callback for each generated token     * @return [RoutingResult] containing the decision and the final output     */    suspend fun route(        userInput: String,        context: BrainContext,        forceCloud: Boolean = false,        forceLocal: Boolean = false,        preferredCloudProvider: String? = null,        preferredCloudModel: String? = null,        generationConfig: GenerationConfig = GenerationConfig.BALANCED,        onToken: (String) -> Unit = {},    ): RoutingResult {        val startNanos = System.nanoTime()        // ─── 1. Parse explicit user intent ────────────────────────────────        val (effectiveInput, decision) = parseExplicitIntent(userInput, forceCloud, forceLocal)        // ─── 2. Check context length vs local model capacity ──────────────        val estimatedTokens = contextInjector.estimateTokensForPrompt(userInput, context)        val localContextLength = context.deviceContext.let {            // Heuristic: if RAM < 2GB, assume small model (2k context)            // Otherwise assume 4k context (default small model)            if (it.availableRamMb < 2048) 2_048 else 4_096        }        val useCloudFirst = decision is RoutingDecision.ExplicitCloud ||            (decision is RoutingDecision.LocalFirst &&                estimatedTokens > localContextLength &&                cloudLlmLayer != null &&                context.userContext.privacySettings.cloudLlmEnabled)        val finalDecision: RoutingDecision = when {            decision is RoutingDecision.ExplicitCloud -> decision            decision is RoutingDecision.ExplicitLocal -> decision            estimatedTokens > localContextLength && cloudLlmLayer != null ->                RoutingDecision.LongContext(estimatedTokens, localContextLength)            else -> decision        }        Timber.tag("NOUS.Router").v(            "Decision: %s (estimated=%d tokens, localCtx=%d)",            finalDecision::class.simpleName, estimatedTokens, localContextLength,        )        // ─── 3. Execute based on decision ─────────────────────────────────        return when (finalDecision) {            is RoutingDecision.ExplicitCloud,            is RoutingDecision.LongContext -> {                if (cloudLlmLayer == null) {                    RoutingResult(                        decision = RoutingDecision.NoFallback,                        output = Result.Success(                            data = SkillOutput.Failure(                                error = com.roshan.persona.common.AppError.Configuration.InvalidProviderConfig(                                    reason = "Cloud LLM layer not available",                                ),                                userMessage = "Cloud AI is not available. Use local AI instead.",                            ),                            correlationId = context.correlationId,                            durationNanos = System.nanoTime() - startNanos,                        ),                    )                } else {                    val result = cloudLlmLayer.process(                        userInput = effectiveInput,                        context = context,                        preferredProviderId = preferredCloudProvider,                        preferredModel = preferredCloudModel,                        generationConfig = generationConfig,                        onToken = onToken,                    )                    RoutingResult(decision = finalDecision, output = result)                }            }            is RoutingDecision.ExplicitLocal -> {                val result = localLlmLayer.process(                    userInput = effectiveInput,                    context = context,                    generationConfig = generationConfig,                    onToken = onToken,                )                RoutingResult(decision = finalDecision, output = result)            }            is RoutingDecision.LocalFirst -> {                // Try local first                val localResult = localLlmLayer.process(                    userInput = effectiveInput,                    context = context,                    generationConfig = generationConfig,                    onToken = onToken,                )                // If local succeeded or returned Partial (low confidence), return immediately                when (localResult) {                    is Result.Success -> {                        // Success or Partial — both are returned to user                        RoutingResult(decision = finalDecision, output = localResult)                    }                    is Result.Partial -> {                        RoutingResult(decision = finalDecision, output = localResult)                    }                    is Result.Failure -> {                        // Local failed — try cloud fallback (if enabled)                        if (cloudLlmLayer != null && context.userContext.privacySettings.cloudLlmEnabled) {                            Timber.tag("NOUS.Router").i("Local failed → falling back to cloud")                            val cloudResult = cloudLlmLayer.process(                                userInput = effectiveInput,                                context = context,                                preferredProviderId = preferredCloudProvider,                                preferredModel = preferredCloudModel,                                generationConfig = generationConfig,                                onToken = onToken,                            )                            RoutingResult(decision = finalDecision, output = cloudResult)                        } else {                            // No cloud fallback available                            RoutingResult(decision = RoutingDecision.NoFallback, output = localResult)                        }                    }                }            }            is RoutingDecision.NoFallback -> {                RoutingResult(                    decision = RoutingDecision.NoFallback,                    output = Result.Success(                        data = SkillOutput.Failure(                            error = com.roshan.persona.common.AppError.Configuration.InvalidProviderConfig(                                reason = "No LLM available (local failed, cloud not enabled)",                            ),                            userMessage = "I couldn't process your request. Local AI failed and cloud AI is disabled. " +                                "Enable cloud in Settings → Privacy, or check your local AI model.",                        ),                        correlationId = context.correlationId,                        durationNanos = System.nanoTime() - startNanos,                    ),                )            }        }    }    /**     * Parse explicit user intent from the input ("ask cloud:" / "ask local:").     *     * @return the cleaned input (with prefix removed) and the routing decision     */    private fun parseExplicitIntent(        userInput: String,        forceCloud: Boolean,        forceLocal: Boolean,    ): Pair<String, RoutingDecision> {        val trimmed = userInput.trim()        if (forceCloud) return trimmed to RoutingDecision.ExplicitCloud        if (forceLocal) return trimmed to RoutingDecision.ExplicitLocal        val cloudMatch = Regex("^(?:ask\\s+cloud|cloud)[:\\s]+(.+)$", RegexOption.IGNORE_CASE).find(trimmed)        if (cloudMatch != null) {            return cloudMatch.groupValues[1].trim() to RoutingDecision.ExplicitCloud        }        val localMatch = Regex("^(?:ask\\s+local|local)[:\\s]+(.+)$", RegexOption.IGNORE_CASE).find(trimmed)        if (localMatch != null) {            return localMatch.groupValues[1].trim() to RoutingDecision.ExplicitLocal        }        return trimmed to RoutingDecision.LocalFirst    }    /**     * Result of routing — contains the decision made and the final output.     */    data class RoutingResult(        val decision: RoutingDecision,        val output: Result<SkillOutput>,    )    /**     * Static factory for creating a [HybridLlmRouter] with all dependencies.     *     * Convenience method for wiring in DI (Module 9 wires this for real).     */    companion object {        /**         * Build a router with cloud disabled (privacy mode).         *         * Used when user hasn't opted in to cloud — only local LLM is available.         */        fun localOnly(            localLlmLayer: LocalLlmLayer,            contextInjector: ContextInjector,        ): HybridLlmRouter = HybridLlmRouter(            localLlmLayer = localLlmLayer,            cloudLlmLayer = null,            contextInjector = contextInjector,        )        /**         * Build a router with cloud enabled (user has opted in).         */        fun withCloud(            localLlmLayer: LocalLlmLayer,            registry: CloudProviderRegistry,            costTracker: LlmCostTracker,            contextInjector: ContextInjector,            credentialVault: CredentialVaultInterface,            brainBus: BrainBus,            providerFactory: (CloudProviderConfig) -> CloudLlmProvider,        ): HybridLlmRouter {            val cloudLayer = CloudLlmLayer(                registry = registry,                costTracker = costTracker,                contextInjector = contextInjector,                credentialVault = credentialVault,                brainBus = brainBus,                providerFactory = providerFactory,            )            return HybridLlmRouter(                localLlmLayer = localLlmLayer,                cloudLlmLayer = cloudLayer,                contextInjector = contextInjector,            )        }    }}/** * Helper to estimate token count for a prompt (used by HybridLlmRouter). */private fun ContextInjector.estimateTokensForPrompt(    userInput: String,    context: BrainContext,): Int {    // Conservative estimate: 4 chars/token for Latin + extra for system prompt    val userInputTokens = ContextInjector.HeuristicTokenEstimator.estimate(userInput)    val systemPromptTokens = ESTIMATED_SYSTEM_PROMPT_TOKENS_ROUTER    val historyTokens = context.conversationHistory.sumOf {        ContextInjector.HeuristicTokenEstimator.estimate(it.userText) +            ContextInjector.HeuristicTokenEstimator.estimate(it.brainResponse)    }    return userInputTokens + systemPromptTokens + historyTokens}/** * Internal constant — used by HybridLlmRouter for token estimation. * Kept here to avoid coupling with CloudLlmLayer's constant. */private const val ESTIMATED_SYSTEM_PROMPT_TOKENS_ROUTER = 250